class Solution:
    def shoppingOffers(self, price, special, needs):
        def dfs(need):
            best = sum(p * c for p, c in zip(price, need))
            for off in special:
                if all(o <= c for o, c in zip(off[:-1], need)):
                    best = min(best, off[-1] + dfs(tuple(c - o for o, c in zip(off[:-1], need))))
            return best
        return dfs(tuple(needs))

