class Solution {
public:
    int shoppingOffers(vector<int>& price, vector<vector<int>>& special, vector<int>& needs) {
        return dfs(price, special, needs);
    }
private:
    int dfs(vector<int>& price, vector<vector<int>>& special, vector<int> need) {
        int best = 0;
        for (int i = 0; i < (int)price.size(); i++) best += price[i] * need[i];
        for (auto& off : special) {
            bool ok = true;
            for (int i = 0; i < (int)price.size() && ok; i++) if (off[i] > need[i]) ok = false;
            if (!ok) continue;
            for (int i = 0; i < (int)price.size(); i++) need[i] -= off[i];
            best = min(best, off.back() + dfs(price, special, need));
            for (int i = 0; i < (int)price.size(); i++) need[i] += off[i];
        }
        return best;
    }
};

