    private int dfs(List<Integer> price, List<List<Integer>> special, List<Integer> need) {
        int best = 0;
        for (int i = 0; i < price.size(); i++) best += price.get(i) * need.get(i);
        for (List<Integer> off : special) {
            boolean ok = true;
            for (int i = 0; i < price.size() && ok; i++) if (off.get(i) > need.get(i)) ok = false;
            if (!ok) continue;
            for (int i = 0; i < price.size(); i++) need.set(i, need.get(i) - off.get(i));
            best = Math.min(best, off.get(price.size()) + dfs(price, special, need));
            for (int i = 0; i < price.size(); i++) need.set(i, need.get(i) + off.get(i));
        }
        return best;
    }
}

