class Solution {
    map<vector<int>, int> memo;
    vector<int> price;
    vector<vector<int>> offers;
    int dfs(vector<int> need) {
        auto it = memo.find(need);
        if (it != memo.end()) return it->second;
        int best = 0;
        for (int i = 0; i < (int)price.size(); i++) best += price[i] * need[i];
        for (auto& off : offers) {
            bool ok = true;
            for (int i = 0; i < (int)price.size() && ok; i++) if (off[i] > need[i]) ok = false;
            if (!ok) continue;
            for (int i = 0; i < (int)price.size(); i++) need[i] -= off[i];
            best = min(best, off.back() + dfs(need));
            for (int i = 0; i < (int)price.size(); i++) need[i] += off[i];
        }
        return memo[need] = best;
    }
public:
    int shoppingOffers(vector<int>& price_, vector<vector<int>>& special, vector<int>& needs) {
        price = price_;
        for (auto& off : special) {
            int sum = 0;
            for (int i = 0; i < (int)price.size(); i++) sum += price[i] * off[i];
            if (off.back() < sum) offers.push_back(off);
        }
        return dfs(needs);
    }
};

