class Solution {
    private Map<List<Integer>, Integer> memo = new HashMap<>();
    private List<Integer> price;
    private List<List<Integer>> offers = new ArrayList<>();

    public int shoppingOffers(List<Integer> price, List<List<Integer>> special, List<Integer> needs) {
        this.price = price;
        for (List<Integer> off : special) {
            int sum = 0;
            for (int i = 0; i < price.size(); i++) sum += price.get(i) * off.get(i);
            if (off.get(price.size()) < sum) offers.add(off);
        }
        return dfs(new ArrayList<>(needs));
    }
    private int dfs(List<Integer> need) {
        Integer cached = memo.get(need);
        if (cached != null) return cached;
        int best = 0;
        for (int i = 0; i < price.size(); i++) best += price.get(i) * need.get(i);
        for (List<Integer> off : offers) {
            boolean ok = true;
            for (int i = 0; i < price.size() && ok; i++) if (off.get(i) > need.get(i)) ok = false;
            if (!ok) continue;
            for (int i = 0; i < price.size(); i++) need.set(i, need.get(i) - off.get(i));
            best = Math.min(best, off.get(price.size()) + dfs(need));
            for (int i = 0; i < price.size(); i++) need.set(i, need.get(i) + off.get(i));
        }
        memo.put(new ArrayList<>(need), best);
        return best;
    }
}

