var shoppingOffers = function(price, special, needs) {
    const good = special.filter(off =>
        off[price.length] < off.slice(0, price.length).reduce((s, c, i) => s + c * price[i], 0));
    const memo = new Map();
    const key = (need) => need.join(',');
    const dfs = (need) => {
        const k = key(need);
        if (memo.has(k)) return memo.get(k);
        let best = 0;
        for (let i = 0; i < price.length; i++) best += price[i] * need[i];
        for (const off of good) {
            let ok = true;
            for (let i = 0; i < price.length && ok; i++) if (off[i] > need[i]) ok = false;
            if (!ok) continue;
            const next = need.map((c, i) => c - off[i]);
            best = Math.min(best, off[price.length] + dfs(next));
        }
        memo.set(k, best);
        return best;
    };
    return dfs(needs.slice());
};
